// === ArcVault Triage - Code Node ===
const MODEL = 'llama-3.3-70b-versatile';

const webhookData = $('Webhook').item.json.body || {};
const rawMessage = webhookData.raw_message || '';
const source = webhookData.source || 'Unknown';

// Defensive parse of OpenAI/Groq's JSON response
let classification;
let parseError = null;
try {
  const apiResponse = $input.item.json;
  const rawText = apiResponse?.choices?.[0]?.message?.content;
  if (!rawText) {
    throw new Error('LLM response missing message content');
  }
  classification = JSON.parse(rawText);
} catch (err) {
  parseError = err.message;
}

// If LLM output is broken, emit error record routed to Escalation
if (parseError || !classification?.category) {
  return {
    json: {
      record_id: `arcvault-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      source,
      raw_message: rawMessage,
      processed_at: new Date().toISOString(),
      model: MODEL,
      classification: null,
      routing: { queue: 'Escalation' },
      escalation_flag: true,
      escalation_reasons: ['llm_output_invalid'],
      error: parseError || 'Missing classification.category'
    }
  };
}

// Normalize entities: guarantee urgency_keywords exists (Step 3 requires urgency signal),
// strip empty-string fields that the LLM sometimes emits for absent entities.
if (!classification.entities || typeof classification.entities !== 'object') {
  classification.entities = {};
}
if (!Array.isArray(classification.entities.urgency_keywords)) {
  classification.entities.urgency_keywords = [];
}
for (const k of Object.keys(classification.entities)) {
  if (classification.entities[k] === '' || classification.entities[k] === null) {
    delete classification.entities[k];
  }
}

// Build escalation reasons
const escalationReasons = [];

if (typeof classification.confidence === 'number' && classification.confidence < 0.7) {
  escalationReasons.push('low_confidence');
}

const lowerMessage = rawMessage.toLowerCase();
const outageKeywords = ['outage', 'down for all users', 'all users affected', 'multiple users affected'];
if (outageKeywords.some(kw => lowerMessage.includes(kw))) {
  escalationReasons.push('outage_or_multi_user_keyword_match');
}

const dollarAmounts = classification.entities?.dollar_amounts || [];
const billingDiscrepancy = dollarAmounts.length >= 2
  ? Math.max(...dollarAmounts) - Math.min(...dollarAmounts)
  : 0;
if (classification.category === 'Billing Issue' && billingDiscrepancy > 500) {
  escalationReasons.push('billing_discrepancy_over_500');
}

// Category to queue mapping
const categoryToQueue = {
  'Bug Report': 'Engineering',
  'Incident/Outage': 'Engineering',
  'Billing Issue': 'Billing',
  'Feature Request': 'Product',
  'Technical Question': 'IT/Security'
};

const escalationFlag = escalationReasons.length > 0;
const queue = escalationFlag
  ? 'Escalation'
  : (categoryToQueue[classification.category] || 'Escalation');

return {
  json: {
    record_id: `arcvault-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    source,
    raw_message: rawMessage,
    processed_at: new Date().toISOString(),
    model: MODEL,
    classification,
    routing: {
      queue,
      llm_suggested_queue: classification.suggested_queue,
      rule_and_llm_agree: classification.suggested_queue === queue
    },
    escalation_flag: escalationFlag,
    escalation_reasons: escalationReasons
  }
};
